      const text = normalized.text;
      const fp = this.makeFingerprint(file);
      const chars = Array.from(text);
      state.novelText = text;
      state.novelChars = chars;
      state.totalChars = chars.length;
      state.currentIndex = 0;
      state.sessionStartIndex = 0;
      state.fingerprint = fp;
      state.chapters = this.detectChapters(text);
      await Storage.saveNovel(fp, text, {
        name: file.name,
        size: file.size,
        lastModified: file.lastModified,
      });
      state.currentIndex = 0;
      state.sessionStartIndex = 0;
      await Storage.saveProgress(fp, 0);
      resolve({ fp, chars, total: state.totalChars, index: state.currentIndex, chapters: state.chapters.length });
